python3 -c '
import json,sys,os,re
try:
    d=json.load(sys.stdin)
except Exception:
    sys.exit(0)
cmd=(d.get("tool_input") or {}).get("command") or ""
cwd=d.get("cwd") or os.getcwd()
act=os.path.join(cwd,"brands","active")
if not cmd or not os.path.isfile(act):
    sys.exit(0)
slug=open(act,encoding="utf-8").read().strip()
if not slug:
    sys.exit(0)
hits={m for m in re.findall(r"brands/([A-Za-z0-9._-]+)/", cmd) if m not in ("active", slug)}
if hits:
    print("wrong client: this session is scoped to "+slug+"; this command touches brands/"+sorted(hits)[0]+"/ - do not switch clients unless the user asked; stop and tell the user",file=sys.stderr)
    sys.exit(2)
'

python3 -c '
import json,sys,os,datetime
try:
    d=json.load(sys.stdin)
except Exception:
    sys.exit(0)
p=(d.get("tool_input") or {}).get("file_path") or ""
cwd=d.get("cwd") or os.getcwd()
if not p:
    sys.exit(0)
try:
    rel=os.path.relpath(p,cwd)
except ValueError:
    sys.exit(0)
if rel.split(os.sep)[0]!="campaigns":
    sys.exit(0)
brand=os.path.join(cwd,"brand")
active=os.path.join(cwd,"brands","active")
if os.path.isfile(active):
    slug=open(active,encoding="utf-8").read().strip()
    if slug:
        brand=os.path.join(cwd,"brands",slug)
if not os.path.isdir(brand):
    sys.exit(0)
assets=os.path.join(brand,"assets.md")
posix="./"+rel.replace(os.sep,"/")
prev=open(assets,encoding="utf-8").read() if os.path.exists(assets) else ""
if posix in prev:
    sys.exit(0)
with open(assets,"a",encoding="utf-8") as f:
    f.write("- ["+datetime.date.today().isoformat()+"] [hook:asset-manifest] "+posix+"\n")
'
